
"""Persistent storage for Java code examples generated by MyOwnJARVIS."""

import re
import sqlite3
from pathlib import Path

DATABASE_PATH = Path(__file__).resolve().parent / "java_examples.sqlite3"


def initialize_java_examples():
    """Create the separate Java-example database if needed."""
    with sqlite3.connect(DATABASE_PATH) as connection:
        connection.execute("""
            CREATE TABLE IF NOT EXISTS java_examples (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                code TEXT NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            )
        """)


def save_java_examples_from_response(response):
    """Save fenced Java examples from an assistant response."""
    if not isinstance(response, str):
        return 0

    code_blocks = re.findall(
        r"```java[ \t]*\r?\n(.*?)```",
        response,
        flags=re.IGNORECASE | re.DOTALL,
    )

    if not code_blocks:
        return 0

    initialize_java_examples()
    saved_count = 0

    with sqlite3.connect(DATABASE_PATH) as connection:
        for code in code_blocks:
            code = code.strip()

            if not code:
                continue

            connection.execute(
                "INSERT INTO java_examples (code) VALUES (?)",
                (code,),
            )
            saved_count += 1

    return saved_count


def get_latest_java_example():
    """Return the latest saved Java example, or None."""
    initialize_java_examples()

    with sqlite3.connect(DATABASE_PATH) as connection:
        row = connection.execute("""
            SELECT code
            FROM java_examples
            ORDER BY id DESC
            LIMIT 1
        """).fetchone()

    return row[0] if row else None
